(function(window2,document2){"use strict";if(window2.RREntryPrompts)return;var startedAt=Date.now(),engaged=false,timer=0,queue=[],running=false;var sessionKey="rr.entry.optionalPrompt.v1";var shown=false;try{shown=window2.sessionStorage.getItem(sessionKey)==="1"}catch(_){}function blocked(){var focused=document2.activeElement;return document2.hidden||document2.body.classList.contains("rr-mobile-onboarding-open")||!!document2.querySelector(".modal.show, .modal-backdrop, .offcanvas.show, .dropdown-menu.show, .rr-pwa-sheet, [data-audience-privacy-dialog]:not([hidden]), #rrCookieNotice:not([hidden]), #rrPwaUpdateToast, #rrPwaPushPrompt, #rrPwaInstallPrompt")||!!(focused&&focused.matches('input, textarea, select, [contenteditable="true"]'))}function schedule(){if(timer||shown||!queue.length)return;timer=window2.setTimeout(run,1e3)}async function run(){timer=0;if(shown||running)return;if(!engaged||document2.hidden)return;if(Date.now()-startedAt<2e4||blocked()){schedule();return}queue.sort(function(a,b){return b.priority-a.priority});var item=queue.shift();if(!item)return;running=true;try{if(await item.show()!==false){shown=true;try{window2.sessionStorage.setItem(sessionKey,"1")}catch(_){}}}catch(_){}running=false;schedule()}function engage(event){if(event.isTrusted===false)return;engaged=true;schedule()}["pointerdown","keydown","scroll"].forEach(function(name){window2.addEventListener(name,engage,{passive:true})});document2.addEventListener("visibilitychange",schedule);window2.RREntryPrompts={blocked,enqueue:function(id,show,priority){if(shown||queue.some(function(item){return item.id===id}))return;queue.push({id,show,priority:priority||0});schedule()}}})(window,document);
